import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Character Building","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/characters/character-creation.md","filePath":"en/guide/characters/character-creation.md"}'),s={name:"en/guide/characters/character-creation.md"};function n(o,a,l,c,d,h){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="character-building" tabindex="-1">Character Building <a class="header-anchor" href="#character-building" aria-label="Permalink to &quot;Character Building&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Availability not established.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Choose a starting history, not a permanent class.</li><li>Backgrounds provide useful competencies and some initial knowledge.</li><li>You can pursue other disciplines through teaching, practice and discovery.</li></ul><p><span id="character-creation-backgrounds"></span><span id="a-starting-history-not-a-class"></span><span id="possible-histories"></span><span id="your-next-steps-remain-open"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Player meaning</th></tr></thead><tbody><tr><td>Background</td><td>Explains where your character learned their first <a href="/Syrolands-Public/en/guide/characters/skills.html">skills</a>.</td></tr><tr><td>Starting competencies</td><td>Include fundamentals so you can begin useful work. Exact packages remain open.</td></tr><tr><td>Future development</td><td>Your initial choices do not lock later skills or <a href="/Syrolands-Public/en/guide/characters/techniques.html">techniques</a>.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>Skills and stats shape a character without a fixed class.</td><td>Keep that freedom, with backgrounds that connect initial capability to a personal history.</td></tr><tr><td>A skill value describes capability.</td><td>Starting knowledge is also explicit; it does not grant every technique in a discipline.</td></tr></tbody></table><p>UO rules vary by era and shard. <a href="https://uo.com/wiki/ultima-online-wiki/player/stats/skills-stats-and-attributes/" target="_blank" rel="noreferrer">Official UO: skills, stats and attributes</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A Workshop Apprentice might begin with Carpentry, Tinkering and basic joinery, then seek a teacher to learn healing. This is an illustrative background, not a confirmed preset.</p><h2 id="progression-trade-offs" tabindex="-1">Progression / trade-offs <a class="header-anchor" href="#progression-trade-offs" aria-label="Permalink to &quot;Progression / trade-offs&quot;">​</a></h2><p>Starting stats, packages, respecialization and treatment of existing characters remain open.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/characters/skills.html">Skills and teachers</a> · <a href="/Syrolands-Public/en/guide/characters/techniques.html">Techniques</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p>Read the <a href="/Syrolands-Public/en/game-design/characters/character-creation.html">Character Building</a> design specification.</p>',18)])])}const g=e(s,[["render",n]]);export{p as __pageData,g as default};
